  n=Math.imul(n ''^ n>>>16,0x21f0aaad); n=Math.imul(n ''^ n>>>15,0x735a2d97);
  return ((n ''^ n>>>15)>>>0)/4294967296;
}
function noise1(x,seed) { const i=floor(x); return lerp(hash(i+seed),hash(i+1+seed),smooth(0,1,x-i))*2-1; }
function height(x,z) { return .24*sin(x*.072+z*.034)+.17*sin(z*.135-x*.043)+.095*cos(x*.23+z*.16)+.055*sin(x*.52-z*.31); }
const groundChest = (x,z,h=1.22) => V(x,height(x,z)+h,z);
const strikes = [{t:5,id:0,d:400,stop:.1}, {t:12,id:1,d:600,stop:.1},
  {t:27,id:2,d:500,stop:.1}, {t:29.5,id:2,d:500,stop:.2}];
const blows = [[1,.25],[2.5,.25],[4,.25],[5,.45],[5.5,.25],[7.5,.9],[8.2,.3],
  [12,.55],[13,.7],[19,.8],[25,.5],[27,.6],[29.5,1],[31.5,.2],[33,.3]];
function motionTime(t) {
  for(const s of strikes) if(t>=s.t && t<s.t+s.stop+.3)
    return s.t+max(0,t-s.t-s.stop)*(s.stop+.3)/.3;
  return t;
}
function traumaAt(t) {
  let level=0,last=0;
  for(const [at,k] of blows) { if(at>t)break; level=min(1,max(0,level-(at-last)*.8)+k);last=at; }
  return max(0,level-(t-last)*.8);
