const ambient=new T.AmbientLight(0xc3d6e2,.24);
const key=new T.DirectionalLight(0xd8edff,2.05);
key.position.set(-44,75,38); key.target.position.set(7,7,0);
key.castShadow=true; key.shadow.mapSize.set(2048,2048);
Object.assign(key.shadow.camera,{left:-59,right:59,top:55,bottom:-55,near:2,far:170});
key.shadow.normalBias=.07; key.shadow.bias=-.00033;
