const weakLight=new T.PointLight(0xffaf42,1.1,10,1.4);scene.add(weakLight);

// Periodic, seeded value noise with independent spatial frequencies, packed into one texture.
function makeNoise() {
  const side=256, pixels=new Uint8Array(side*side*4);
  for(let ch=0;ch<4;ch++){
    const n=[8,16,32,64][ch],grid=Float32Array.from({length:n*n},random);
    for(let y=0;y<side;y++)for(let x=0;x<side;x++){
      const gx=x*n/side,gy=y*n/side,ix=floor(gx),iy=floor(gy);
      const sx=smooth(0,1,gx-ix),sy=smooth(0,1,gy-iy);
      const g=(a,b)=>grid[(a%n)+(b%n)*n];
      pixels[(y*side+x)*4+ch]=255*lerp(lerp(g(ix,iy),g(ix+1,iy),sx),lerp(g(ix,iy+1),g(ix+1,iy+1),sx),sy);
    }
  }
  const tex=new T.DataTexture(pixels,side,side,T.RGBAFormat);
  tex.wrapS=tex.wrapT=T.RepeatWrapping;tex.magFilter=T.LinearFilter;
  tex.minFilter=T.LinearMipmapLinearFilter;tex.generateMipmaps=true;tex.needsUpdate=true;return tex;
