const cloudCode=`
uniform sampler2D noiseMap;
uniform float time,flash;
float clouds(vec2 uv) {
  vec4 a=texture2D(noiseMap,uv);
  vec4 b=texture2D(noiseMap,uv*1.93+vec2(.37,.16));
  return dot(a,vec4(.49,.27,.135,.057))+b.b*.048;
}
vec3 storm(vec3 d) {
  float h=max(0.,d.y), layer=.35+h*.96;
  vec2 p=d.xz/layer*vec2(.158,.208)+vec2(-time*.00085,time*.00019);
  float broad=clouds(p+vec2(.46,.19));
  vec2 warp=texture2D(noiseMap,p*.61+vec2(.2,.8)).gb;
  float n=clouds(p+warp*.069);
  float l=clouds(p+warp*.069+vec2(.008,.004));
  float opening=smoothstep(.40,.73,n);
  float glow=pow(max(0.,dot(d,normalize(vec3(.85,.17,-.41)))),7.);
  vec3 low=vec3(.25,.36,.43), high=vec3(.034,.052,.079);
  vec3 sky=mix(low,high,smoothstep(-.02,.87,h));
  sky+=vec3(.32,.35,.34)*glow*(.43+.78*opening);
  float cover=smoothstep(.28,.67,1.-n);
  vec3 underside=mix(vec3(.060,.078,.103),vec3(.18,.21,.235),broad);
  sky=mix(sky,underside,cover*smoothstep(-.12,.26,h)*.91);
  sky+=clamp((n-l)*2.3,-.12,.18)*vec3(.72,.84,.95)*smoothstep(-.06,.23,h);
  float fringe=pow(max(0.,1.-abs(d.y-.033)),18.);
  sky+=vec3(.11,.145,.16)*fringe;
  return max(vec3(.009),sky)*(1.+flash*1.85)+vec3(.27,.34,.44)*flash;
