const skyMaterial=new T.ShaderMaterial({side:T.BackSide,depthWrite:false,fog:false,
 uniforms:{noiseMap:U(noiseTex),time:clockU,flash:flashU},
 vertexShader:`varying vec3 ray;void main(){ray=position;vec4 p=projectionMatrix*modelViewMatrix*vec4(position,1.);gl_Position=p.xyww;}`,
 fragmentShader:`varying vec3 ray;`+cloudCode+`
 void main(){gl_FragColor=vec4(storm(normalize(ray)),1.);
 #include <tonemapping_fragment>
 #include <encodings_fragment>
 }`});
const sky=new T.Mesh(new T.SphereGeometry(900,38,20),skyMaterial);
sky.renderOrder=-100;sky.frustumCulled=false;scene.add(sky);
