scene.environment=stormEnvironment.texture;pmrem.dispose();

// Distant peaks are closed, ridged landforms. Separate ranges fade into the rain.
function makeRange(radius,base,amplitude,colour,seed) {
  const positions=[],colors=[],verts=[],indices=[],sectors=280,rows=7;
  const c=new T.Color(colour);
  for(let i=0;i<=sectors;i++){
    const a=i/sectors*TAU, waves=(f,k)=>sin(a*f+k);
    const ridge=base+amplitude*(.28+.34*abs(waves(7,seed))+.22*waves(13,seed*.8)+.17*waves(27,seed+1)+.09*waves(57,seed));
    for(let j=0;j<rows;j++){
      const u=j/(rows-1), r=radius+u*42+waves(9,seed)*6+waves(24,seed)*2.3;
