      verts.push(V(cos(a)*r,elevation,sin(a)*r));
    }
  }
  for(let i=0;i<sectors;i++)for(let j=0;j<rows-1;j++){
    const k=i*rows+j; indices.push(k,k+1,k+rows,k+1,k+rows+1,k+rows);
  }
  for(let i=0;i<indices.length;i+=3) {
    const a=verts[indices[i]],b=verts[indices[i+1]],d=verts[indices[i+2]];
    const n=V().subVectors(b,a).cross(V().subVectors(d,a)).normalize();
    const brightness=.79+.32*abs(n.dot(V(-.6,.5,.55)))+.17*hash(i+seed);
    for(const p of [a,b,d]){positions.push(p.x,p.y,p.z);colors.push(c.r*brightness,c.g*brightness,c.b*brightness);}
  }
  const g=new T.BufferGeometry();g.setAttribute('"'position',new T.Float32BufferAttribute(positions,3));
  g.setAttribute('color',new T.Float32BufferAttribute(colors,3));
  scene.add(new T.Mesh(g,new T.MeshBasicMaterial({vertexColors:true,side:T.DoubleSide})));
