function landscape() {
  const pos=[],col=[],ind=[],seg=210,bands=72;
  for(let j=0;j<=bands+2;j++)for(let i=0;i<=seg;i++){
    const a=i/seg*TAU,r=min(1,j/bands)*90+(j>bands?(j-bands)*-.8:0);
    const x=cos(a)*r,z=sin(a)*r,y=height(x,z)-(j>bands?(j-bands)*(10+3*sin(a*47)):0);
    pos.push(x,y,z);
    const s=.5+.26*sin(x*.12+z*.08)+.19*cos(z*.19-x*.055);
    const c=new T.Color(0x465542).lerp(new T.Color(0x768365),s);
    if(j>bands)c.setHex(0x454f52);
    col.push(c.r,c.g,c.b);
  }
  for(let j=0;j<bands+2;j++)for(let i=0;i<seg;i++){const a=j*(seg+1)+i,b=a+seg+1;ind.push(a,a+1,b,a+1,b+1,b);}
  const g=new T.BufferGeometry();g.setIndex(ind);g.setAttribute('position',new T.Float32BufferAttribute(pos,3));
  g.setAttribute('color',new T.Float32BufferAttribute(col,3));g.computeVertexNormals();
  const mat=new T.MeshStandardMaterial({vertexColors:true,roughness:.9,metalness:.06,envMapIntensity:.55});
  mat.onBeforeCompile=s=>{
    Object.assign(s.uniforms,{terrainNoise:U(noiseTex),wet:wetU});
    s.vertexShader='varying vec3 groundP;\\n'+s.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\\ngroundP=position;');
    s.fragmentShader='varying vec3 groundP; uniform sampler2D terrainNoise; uniform float wet;\\n'+s.fragmentShader
      .replace('#include <color_fragment>',"'`#include <color_fragment>
      vec4 sod=texture2D(terrainNoise,groundP.xz*.058);
      float scree=texture2D(terrainNoise,groundP.xz*.23).a;
      float pools=smoothstep(.59,.75,sod.r*.72+sod.g*.28);
      diffuseColor.rgb*=.65+.45*sod.b+.24*scree;
      diffuseColor.rgb=mix(diffuseColor.rgb,vec3(.042,.069,.073),pools*(.16+.68*wet));
      diffuseColor.rgb*=1.-wet*.25;`)
      .replace('"'#include <roughnessmap_fragment>','#include <roughnessmap_fragment>\\nroughnessFactor=max(.12,roughnessFactor-pools*wet*.22);');
  };
  const mesh=new T.Mesh(g,mat);mesh.receiveShadow=true;scene.add(mesh);return mat;
}
const groundMat=landscape();
